const X = window.GYX;

/* 📸 TA 的相册：TA 发给你的每张照片、画的涂鸦、寄的明信片，自动收进一本相册；TA 还会时不时拍下生活碎片（今天的晚霞、路过的猫、咖啡杯……）放进来，配一句话 */
if (window.__gyxAlbum) return; window.__gyxAlbum = 1;
X.feat('gyxAlbum', { n: '📸 TA 的相册', desc: 'TA 发的照片自动收进相册，TA 还会拍生活碎片' });
